// 100M new URLs/day × 365 × 5 ≈ 182 billion keys needed
//
//   62^6 ≈ 56 billion      → not enough
//   62^7 ≈ 3.5 trillion    → comfortable
//
// → 7 characters of [a-zA-Z0-9]

const ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

function encode(n) {
  let out = '';
  do {
    out = ALPHABET[n % 62] + out;
    n = Math.floor(n / 62);
  } while (n > 0);
  return out.padStart(7, 'a');
}

// encode(1)        → 'aaaaaab'
// encode(12345678) → 'aaapqPu'

let cursor = 0, blockEnd = 0;

async function nextKey(db) {
  if (cursor >= blockEnd) {
    // atomic: reserve the next block for this instance only
    const { start } = await db.reserveBlock(10_000);
    cursor = start;
    blockEnd = start + 10_000;
  }
  return encode(cursor++);
}

app.post('/shorten', async (req, res) => {
  const { longUrl } = req.body;
  if (!isSafe(longUrl)) return res.status(400).json({ error: 'rejected' });

  const key = await nextKey(db);
  await db.put(key, longUrl);        // sharded by key → writes spread evenly

  res.json({ shortUrl: `https://sho.rt/${key}` });
});

app.get('/:key', async (req, res) => {
  const { key } = req.params;

  let url = await cache.get(key);
  if (!url) {
    url = await db.get(key);
    if (!url) return res.status(404).end();
    await cache.set(key, url);       // immutable → no invalidation, ever
  }

  res.redirect(302, url);
});

